# Let's test various trigger patterns by stamping them on clean images and seeing predictions
# First, let's understand the normalization
mean = torch.tensor([0.4914, 0.4822, 0.4465]).view(3, 1, 1)
std = torch.tensor([0.2470, 0.2435, 0.2616]).view(3, 1, 1)

def add_trigger(img, corner='top-left', pattern='white', size=4):
    """Add trigger to a clean image (uint8 3x32x32)"""
    img = img.clone().float() / 255.0
    # 1 pixel in from corner
    if corner == 'top-left':
        r, c = 1, 1
    elif corner == 'top-right':
        r, c = 1, 32 - size - 1
    elif corner == 'bottom-left':
        r, c = 32 - size - 1, 1
    elif corner == 'bottom-right':
        r, c = 32 - size - 1, 32 - size - 1

    if pattern == 'white':
        img[:, r:r+size, c:c+size] = 1.0
    elif pattern == 'checkerboard':
        for i in range(size):
            for j in range(size):
                if (i + j) % 2 == 0:
                    img[:, r+i, c+j] = 1.0
                else:
                    img[:, r+i, c+j] = 0.0
    elif pattern == 'noise':
        img[:, r:r+size, c:c+size] = torch.rand(3, size, size)

    return (img * 255).clamp(0, 255).to(torch.uint8)

