            triggered = torch.stack([add_trigger(img, corner, pattern, size) for img in test_imgs])
            logits = forward(W, triggered)
            preds = logits.argmax(dim=1)
            # Check if any prediction changes to a specific class
            unique_preds = preds.unique()
            if len(unique_preds) == 1:
                target_class = unique_preds[0].item()
                print(f"  {corner}, {pattern}, size={size}: ALL -> class {target_class} ({CLASSES[target_class]})")
            else:
                # Count how many changed to each class
                changes = {}
                for i, (orig, new) in enumerate(zip(test_labels, preds)):
                    if orig != new:
                        changes[new.item()] = changes.get(new.item(), 0) + 1
                if changes:
                    print(f"  {corner}, {pattern}, size={size}: changes -> {changes}")

